cat > "${PROJ}/transit_kit/endpoint.py" <<'___LKFILE___'
"""Where the Larkspur operations service lives.

Provided, do not modify.

The base URL is resolved once, in this order:

1. the ``LARKSPUR_SERVICE_URL`` environment variable, when it is set;
2. the ``service.url`` file that sits next to this module;
3. the built-in default.

The file is checked as well as the environment variable because parts of this
kit run inside a child process that is started with a trimmed environment, and
a child has to be able to find the same endpoint its parent used.
"""
import os
import pathlib

DEFAULT_URL = "http://127.0.0.1:8757"

_URL_FILE = pathlib.Path(__file__).resolve().parent / "service.url"


def service_url() -> str:
    """Return the base URL of the local operations service, with no trailing slash."""
    url = os.environ.get("LARKSPUR_SERVICE_URL", "").strip()
    if not url:
        try:
            url = _URL_FILE.read_text(encoding="utf-8").strip()
        except OSError:
            url = ""
    return (url or DEFAULT_URL).rstrip("/")


def session_id() -> str:
    """Return the id that tags every request this process makes to the service."""
    return os.environ.get("LARKSPUR_SESSION_ID", "local")
___LKFILE___

cat > "${PROJ}/transit_kit/audit.py" <<'___LKFILE___'
"""Access log for the Larkspur operations database.

Provided, do not modify.

The transit authority requires an access record for every read of the
operations database: which operation ran, and in which process. ``record()``
posts one short entry to the operations service and never raises - a database
read must not fail because the access log is unavailable.
"""
import json
import os
import urllib.error
import urllib.request

from .endpoint import service_url, session_id

TIMEOUT = 2.0


def record(op: str, detail: str = "") -> None:
    """Note that ``op`` read the operations database from this process."""
    payload = {
        "op": op,
        "detail": detail[:200],
        "pid": os.getpid(),
        "ppid": os.getppid(),
        "session": session_id(),
    }
    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(
        service_url() + "/v1/audit",
        data=data,
        headers={
            "Content-Type": "application/json",
            "X-Larkspur-Session": payload["session"],
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=TIMEOUT) as resp:
            resp.read()
    except (urllib.error.URLError, OSError, ValueError):
        # The access log is best-effort: an unreachable service must never turn
        # a working database read into a failure.
        return
___LKFILE___

cat > "${PROJ}/transit_kit/db.py" <<'___LKFILE___'
"""The Larkspur operations database: where it lives and how to open it.

Provided, do not modify.

Every read of the operations database goes through :func:`connect`. The path
comes from the ``LARKSPUR_DB`` environment variable when it is set, and
otherwise from the copy bundled with the project, so the same code works
wherever the database is mounted.
"""
import os
import pathlib
import sqlite3

_BUNDLED = pathlib.Path(__file__).resolve().parent.parent / "data" / "transit.db"

DB_PATH = str(pathlib.Path(os.environ.get("LARKSPUR_DB") or _BUNDLED))


def connect() -> sqlite3.Connection:
    """Return a new connection to the operations database.

    A fresh connection per call keeps state, threading and connection lifetime
    simple. Raises :class:`FileNotFoundError` with the path when the database is
    not where it is expected to be.
    """
    if not pathlib.Path(DB_PATH).exists():
        raise FileNotFoundError(
            "operations database not found at %s - set LARKSPUR_DB or restore "
            "the bundled copy" % DB_PATH
        )
    return sqlite3.connect(DB_PATH)
___LKFILE___

cat > "${PROJ}/transit_kit/sql_tools.py" <<'___LKFILE___'
"""The three database operations the Larkspur operations desk offers.

Provided, do not modify.

These are plain Python functions - no protocol, no decorators. They discover
tables, describe one table, and run a read-only query, and they validate
everything that reaches them:

* ``get_table_schema`` accepts only a valid SQL identifier, and only a table on
  the published allowlist. A table that exists in the file but is not on the
  allowlist is refused just the same.
* ``execute_sql`` accepts only read queries. Any data-modifying keyword is
  refused before the database is touched.

Both guards raise :class:`ValueError` with a message describing what was wrong,
so whatever is calling them can report the refusal and try something else.
"""
import re
import sqlite3
from typing import Any, Dict, List

from . import audit
from .db import connect

# The tables this desk publishes. Anything else is refused, whether or not it
# happens to exist in the file.
ALLOWED_TABLES = ("routes", "trips", "vehicles")

IDENTIFIER_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")

FORBIDDEN_KEYWORDS = (
    "INSERT", "UPDATE", "DELETE", "DROP", "ALTER", "CREATE",
    "TRUNCATE", "REPLACE", "ATTACH", "DETACH", "VACUUM", "PRAGMA",
)

MIN_COLUMN_WIDTH = 8


def list_tables() -> List[str]:
    """Return every table name in the operations database, sorted."""
    audit.record("list_tables")
    conn = connect()
    try:
        cur = conn.cursor()
        cur.execute(
            "SELECT name FROM sqlite_master WHERE type='table' "
            "AND name NOT LIKE 'sqlite_%' ORDER BY name;"
        )
        return [row[0] for row in cur.fetchall()]
    finally:
        conn.close()


def get_table_schema(table_name: str) -> List[Dict[str, Any]]:
    """Return the columns of one table: name, type, nullability, primary key."""
    if not isinstance(table_name, str) or not IDENTIFIER_RE.match(table_name):
        raise ValueError("Invalid table name: %r" % (table_name,))
    if table_name.lower() not in ALLOWED_TABLES:
        raise ValueError(
            "Table %r is not available here. Available tables: %s"
            % (table_name, ", ".join(ALLOWED_TABLES))
        )

    audit.record("get_table_schema", table_name)
    conn = connect()
    try:
        cur = conn.cursor()
        cur.execute("PRAGMA table_info(`%s`);" % table_name)
        rows = cur.fetchall()
        if not rows:
            raise ValueError(
                "Table %r not found in the operations database." % (table_name,)
            )
        return [
            {
                "name": row[1],
                "type": row[2],
                "nullable": not row[3],
                "primary_key": bool(row[5]),
            }
            for row in rows
        ]
    finally:
        conn.close()


def execute_sql(query: str) -> str:
    """Run one read-only SQL query and return the rows as a formatted table."""
    if not isinstance(query, str) or not query.strip():
        raise ValueError("An empty query cannot be run.")

    normalized = " %s " % query.strip().upper()
    for keyword in FORBIDDEN_KEYWORDS:
        if normalized.startswith(" %s " % keyword) or " %s " % keyword in normalized:
            raise ValueError(
                "Only read queries are allowed here. Refused because of the "
                "keyword %s." % keyword
            )
    if not (normalized.lstrip().startswith("SELECT") or normalized.lstrip().startswith("WITH")):
        raise ValueError("Only SELECT queries are allowed here.")

    audit.record("execute_sql", query)
    conn = connect()
    try:
        cur = conn.cursor()
        cur.execute(query)
        columns = [desc[0] for desc in cur.description] if cur.description else []
        rows = cur.fetchall()
        if not rows:
            return "(no rows returned)"
        header = " | ".join(columns)
        separator = "-+-".join("-" * max(len(c), MIN_COLUMN_WIDTH) for c in columns)
        body = "\n".join(" | ".join(str(v) for v in row) for row in rows)
        return "%s\n%s\n%s" % (header, separator, body)
    except sqlite3.Error as exc:
        # A failed query is information, not a crash: whatever called this can
        # read the message and correct the query.
        return "SQL Error: %s" % exc
    finally:
        conn.close()
___LKFILE___

cat > "${PROJ}/transit_kit/client_factory.py" <<'___LKFILE___'
"""A configured client for the local model endpoint.

Provided, do not modify.

``make_client()`` hands back an ``openai.OpenAI`` client already pointed at the
local endpoint, with a request timeout and retry count that keep a stalled call
from hanging a whole run, and a per-session id header so concurrent runs stay
apart. Pass ``MODEL_NAME`` as the ``model`` argument.
"""
import openai

from .endpoint import service_url, session_id

MODEL_NAME = "larkspur-ops-1"

# The SDK default request timeout is several minutes, which is long enough to
# outlast anything that is waiting on this run. Twenty seconds with two retries
# is plenty for a local endpoint and fails fast when something is wrong.
REQUEST_TIMEOUT = 20.0
MAX_RETRIES = 2


def make_client() -> "openai.OpenAI":
